function [f] = srp_box(lx, ly, lz, alpha, rho_s, rho_d)
%SRP_BOX  srp.buildBox(Lx, Ly, Lz, opt): the six body facets of a box (+x, -x, +y, -y, +z, -z) with the same optics.
%   lx: real[1] (passed a plain number)
%   ly: real[1] (passed a plain number)
%   lz: real[1] (passed a plain number)
%   alpha: real[1] (passed a plain number)
%   rho_s: real[1] (passed a plain number)
%   rho_d: real[1] (passed a plain number)
%   returns f: ScFacets (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    f = asils.models.srp.ScFacets_zero();
    f = asils.models.srp.ScFacets_zero();
    z = [0; 0; 0];
    f = asils.models.srp.facet_add(f, 1, [1; 0; 0], (ly * lz), alpha, rho_s, rho_d, z, false);
    f = asils.models.srp.facet_add(f, 1, [(-(1)); 0; 0], (ly * lz), alpha, rho_s, rho_d, z, false);
    f = asils.models.srp.facet_add(f, 1, [0; 1; 0], (lx * lz), alpha, rho_s, rho_d, z, false);
    f = asils.models.srp.facet_add(f, 1, [0; (-(1)); 0], (lx * lz), alpha, rho_s, rho_d, z, false);
    f = asils.models.srp.facet_add(f, 1, [0; 0; 1], (lx * ly), alpha, rho_s, rho_d, z, false);
    f = asils.models.srp.facet_add(f, 1, [0; 0; (-(1))], (lx * ly), alpha, rho_s, rho_d, z, false);
end
